import React, { useState } from 'react';

const languages = [
  { code: 'fa', name: 'فارسی', flag: '🇮🇷' },
  { code: 'en', name: 'English', flag: '🇬🇧' },
  { code: 'tr', name: 'Türkçe', flag: '🇹🇷' },
  { code: 'ru', name: 'Русский', flag: '🇷🇺' },
  { code: 'ar', name: 'العربية', flag: '🇸🇦' },
  { code: 'es', name: 'Español', flag: '🇪🇸' },
  { code: 'fr', name: 'Français', flag: '🇫🇷' }
];

function LanguageSelector({ onSelect }) {
  const [selected, setSelected] = useState('fa');

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#FF6B35]/20 to-[#1A1A2E] flex items-center justify-center p-4">
      <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 max-w-md w-full border border-white/20">
        <div className="text-center mb-8">
          <div className="text-6xl mb-3">⛏️</div>
          <h1 className="text-3xl font-bold text-white">Coin Mining</h1>
          <p className="text-gray-400 mt-1">انتخاب زبان / Choose Language</p>
        </div>
        <div className="grid grid-cols-2 gap-3">
          {languages.map((lang) => (
            <button
              key={lang.code}
              onClick={() => {
                setSelected(lang.code);
                onSelect(lang.code);
              }}
              className={`p-4 rounded-2xl border-2 transition-all duration-300 ${
                selected === lang.code
                  ? 'border-[#FF6B35] bg-[#FF6B35]/10 shadow-lg scale-105'
                  : 'border-white/20 hover:border-white/40 bg-white/5'
              }`}
            >
              <span className="text-3xl block">{lang.flag}</span>
              <span className="font-medium text-white text-sm mt-1 block">{lang.name}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

export default LanguageSelector;
